21	export const formatTable = (data, columnWidth = []) => {
22	  const fixedWidthPlaceholder = columnWidth.map((item) => {
23	    return typeof item === 'number' ? ' '.repeat(item) : item;
24	  });
25	
26	  const columnSizes = [fixedWidthPlaceholder, ...data]
27	    .map((row) => row.map((cell) => String(cell)))
28	    .reduce((acc, row) => {
29	      row.forEach((cell, index) => {
30	        const cellLength = stringLength(cell);
31	        acc[index] = Math.max(acc[index] ?? 0, cellLength);
32	      });
33	      return acc;
34	    }, []);
35	
36	  return data
37	    .map((row) => row.map((cell) => String(cell)))
38	    .map((row) => {
39	      return (
40	        row
41	          .map((cell, index) => {
42	            const isLastColumn = index === row.length - 1;
43	            if (isLastColumn) {
44	              return cell;
45	            }
46	            const rightPaddingLength = columnSizes[index] - stringLength(cell) ?? 0;
47	            return cell + ' '.repeat(rightPaddingLength);
48	          })
49	          .join(SEPARATOR)
50	          // empty trailing cells would otherwise pad the line with meaningless spaces
51	          .trimEnd()
52	      );
53	    })
54	    .join('\n');
55	};
